<?php
require_once __DIR__ . '/_vault_helpers.php';
try { $db=vault_db(); $actor=vault_require_auth(); $d=vault_input(); vault_require_csrf($d); vault_require_verified(); $id=(int)($d['document_id']??0); $code=trim((string)($d['code']??'')); $ch=$_SESSION['vault_download_challenge']??null; if(!$ch||$ch['actor']!==$actor||$ch['document_id']!==$id||$ch['expires']<time()){unset($_SESSION['vault_download_challenge']);ApiResponse::forbidden('Verification expired. Request a new code.');exit;} if(($ch['attempts']??0)>=5){unset($_SESSION['vault_download_challenge']);ApiResponse::forbidden('Too many invalid attempts.');exit;} $_SESSION['vault_download_challenge']['attempts']++; if(!preg_match('/^\d{6}$/',$code)||!password_verify($code,$ch['hash'])){ApiResponse::forbidden('Invalid verification code.');exit;} $doc=vault_require_document_access($db,$id,$actor); $_SESSION['vault_download_grant']=['actor'=>$actor,'document_id'=>$id,'expires'=>time()+120,'token'=>bin2hex(random_bytes(24))]; unset($_SESSION['vault_download_challenge']); vault_log($db,(int)$doc['owner_id'],$actor,$id,'download_verified'); ApiResponse::success(['download_token'=>$_SESSION['vault_download_grant']['token']],'Download verified.'); } catch(Throwable $e){Logger::error('Vault download verification failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to verify download.');}